    {
      "type": "SCOPE_CREEP",
      "severity": "HIGH",
      "location": "§2",
      "proposalQuote": "AI demand forecasting to predict stock needs weeks in advance.",
      "explanation": "The client requested an inventory dashboard and low-stock alerts, not predictive demand forecasting and supplier scoring modules.",
      "fix": "Remove the AI demand forecasting, supplier scoring, and automated reorder modules from the scope."
    },
    {
      "type": "UNREALISTIC_TIMELINE",
      "severity": "HIGH",
      "location": "§3",
      "proposalQuote": "deliver the complete suite — including the platform migration and all analytics modules — within 8 weeks",
      "explanation": "Delivering an unrequested full data migration plus multiple AI analytics modules across 6 warehouses in only 8 weeks is highly unrealistic.",
      "fix": "Realign the project schedule to deliver a 3-month single-warehouse pilot and a 6-month full rollout without the migration."
    }
  ],
  "scores": [
    {
      "id": "scope_clarity",
      "label": "Scope & Deliverables Clarity",
      "score": 2,
      "strengths": "The proposal clearly lists core features such as real-time dashboard visibility across all 6 warehouses.",
      "weaknesses": "The proposal relies on high-level feature bullets in §2 without defining deliverable boundaries, role-based access, or onboarding specifics.",
      "citations": [
        {
          "source": "proposal",
          "section": "§2",
          "quote": "Real-time dashboard across all 6 warehouses, plus predictive analytics on top."
        }
      ],
      "note": null
    },
    {
      "id": "pricing_clarity",
      "label": "Pricing Clarity",
      "score": 3,
      "strengths": "The proposal provides a clear total figure that falls within the client's stated budget range and covers the first year of support.",
      "weaknesses": "In §4, only a lump-sum price of €98,000 is given without any itemized cost breakdown across modules or support.",
      "citations": [
        {
          "source": "proposal",
          "section": "§4",
          "quote": "Total project cost: €98,000 , covering the full suite described above"
        }
      ],
      "note": null
    },
